def render_marketing_site() -> None:
    """Render the signed-out Sprint 51 marketing website."""
    _marketing_css()
    try:
        raw = st.query_params.get("public", "home")
        page = raw[0] if isinstance(raw, list) else raw
    except Exception:
        page = "home"
    routes = {
        "home": _home,
        "product": _product,
        "features": _product,
        "solutions": _solutions,
        "pricing": _pricing,
        "resources": _resources,
        "company": _company,
        "contact": _contact,
        "security": lambda: _legal_page("security"),
        "privacy": lambda: _legal_page("privacy"),
        "terms": lambda: _legal_page("terms"),
    }
    routes.get(str(page or "home").lower(), _home)()
